import pyomo.environ as pyo

DATA = {
    "lights": ["LED", "FLUO"],
    "electricity_per_hour": {"LED": 5, "FLUO": 8},
    "changes_per_decade": {"LED": 3, "FLUO": 4},
    "min_fluoro_fraction": 0.30,
    "min_total_fixtures": 300,
    "max_total_electricity": 2000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.LIGHTS = pyo.Set(initialize=d["lights"])

    model.install = pyo.Var(
        model.LIGHTS,
        domain=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["changes_per_decade"][i] * m.install[i] for i in m.LIGHTS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_fixtures_rule(m):
        return sum(m.install[i] for i in m.LIGHTS) >= d["min_total_fixtures"]

    model.total_fixtures = pyo.Constraint(rule=total_fixtures_rule)

    def electricity_rule(m):
        return sum(
            d["electricity_per_hour"][i] * m.install[i] for i in m.LIGHTS
        ) <= d["max_total_electricity"]

    model.electricity_limit = pyo.Constraint(rule=electricity_rule)

    def fluoro_share_rule(m):
        frac = d["min_fluoro_fraction"]
        return m.install["FLUO"] >= frac * sum(m.install[i] for i in m.LIGHTS)

    model.fluoro_share = pyo.Constraint(rule=fluoro_share_rule)

    return model


