import pyomo.environ as pyo

DATA = {
    "light_types": ["LED", "FLUOR"],
    "electricity_per_hour": {"LED": 5, "FLUOR": 8},
    "changes_per_decade": {"LED": 3, "FLUOR": 4},
    "min_fluor_share": 0.30,
    "min_total_fixtures": 300,
    "max_total_electricity": 2000,
    "GOLD_ANSWER": None,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    types = d["light_types"]

    m = pyo.ConcreteModel()

    m.I = pyo.Set(initialize=types)

    m.x = pyo.Var(m.I, domain=pyo.NonNegativeIntegers, bounds=(0, None))

    def _obj_rule(mm):
        return sum(d["changes_per_decade"][i] * mm.x[i] for i in mm.I)

    m.obj = pyo.Objective(rule=_obj_rule, sense=pyo.minimize)

    # min_fluor_share * total <= x_FLUOR  -> cleared of denominators
    def _fluor_rule(mm):
        return (
            d["min_fluor_share"] * sum(mm.x[i] for i in mm.I)
            <= mm.x["FLUOR"]
        )

    m.fluor_share = pyo.Constraint(rule=_fluor_rule)

    # at least min_total_fixtures total fixtures
    def _total_rule(mm):
        return sum(mm.x[i] for i in mm.I) >= d["min_total_fixtures"]

    m.total_fixtures = pyo.Constraint(rule=_total_rule)

    # at most max_total_electricity total electricity
    def _elec_rule(mm):
        return (
            sum(d["electricity_per_hour"][i] * mm.x[i] for i in mm.I)
            <= d["max_total_electricity"]
        )

    m.total_electricity = pyo.Constraint(rule=_elec_rule)

    return m
